theorem derivedOpenRestrictionSuccessive
    {X Y X' Y' X'' Y'' : Scheme.{u}}
    {f : X ⟶ Y} {j : Y' ⟶ Y} {f' : X' ⟶ Y'} {i : X' ⟶ X}
    {j' : Y'' ⟶ Y'} {f'' : X'' ⟶ Y''} {i' : X'' ⟶ X'}
    [IsOpenImmersion j] [IsOpenImmersion i]
    [IsOpenImmersion j'] [IsOpenImmersion i']
    (sq : IsPullback i f' f j) (sq' : IsPullback i' f'' f' j') :
    DirectImageSuccessiveRestriction Λ sq.toCommSq sq'.toCommSq
